      socket.onclose = () => {
        reconnectTimer = window.setTimeout(connect, Math.min(30_000, 1000 * 2 ** retry++))
      }
    }
    connect()

    return () => {
      clearInterval(flushTimer)
      clearTimeout(reconnectTimer)
      socket.onclose = null
      socket.close()
    }
  }, [queryClient])
