      ))}
      <form action={action}>
        <input name="text" />
        <SubmitButton />
      </form>
    </>
  )
}
```

## مثال متكامل: نموذج تواصل مع التحقق من المدخلات
تتحقق الدالة من الحقول وتعيد الأخطاء كحالة، ولا تستدعي الـ API إلا عندما تكون المدخلات صحيحة. لا حاجة إلى `useState` للتحميل أو الأخطاء:

```tsx
type ContactState = {
  ok: boolean
  values: { email: string; message: string }
  errors: Partial<Record<'email' | 'message', string>>
}

async function sendContact(_prev: ContactState, formData: FormData): Promise<ContactState> {
  const values = { email: String(formData.get('email') ?? ''), message: String(formData.get('message') ?? '') }
  const errors: ContactState['errors'] = {}
  if (!values.email.includes('@')) errors.email = 'Enter a valid email'
  if (values.message.length < 10) errors.message = 'Write at least 10 characters'
  if (Object.keys(errors).length) return { ok: false, values, errors }

  await fetch('/api/messages', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(values),
  })
  return { ok: true, values, errors: {} }
}

export function ContactForm() {
  const [state, formAction] = useActionState(sendContact, { ok: false, values: { email: '', message: '' }, errors: {} })
  if (state.ok) return <p>Thanks! I'll reply soon.</p>

  // React resets uncontrolled fields after an action, so defaultValue restores them on errors
  return (
    <form action={formAction}>
      <input name="email" type="email" defaultValue={state.values.email} aria-invalid={!!state.errors.email} />
      {state.errors.email && <p role="alert">{state.errors.email}</p>}
      <textarea name="message" defaultValue={state.values.message} aria-invalid={!!state.errors.message} />
      {state.errors.message && <p role="alert">{state.errors.message}</p>}
      <SubmitButton />
    </form>
  )
}
```

## الخلاصة
- عدد أقل من أزواج `useState` و `useEffect` لحالات التحميل والأخطاء
- النماذج تعمل مع `FormData` مباشرة
- واجهة الانتظار مدمجة
